'use client';
// @interlace/time-series v1.1.1 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/time-series
// What changed since: https://ds.interlace.tools/c/time-series#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — TimeSeries
 *
 * One metric over time, with the actions that moved it drawn ON the curve.
 *
 * ## The annotation is the point
 *
 * A line going up is a fact. A line going up with a publish marker at the
 * inflection is an *argument*. Everything else in this component — grid, axis,
 * crosshair — is chrome that exists so the annotation can be read against a
 * scale. If you are adding a feature here and it does not help someone connect
 * a thing they did to a number that moved, it probably belongs elsewhere.
 *
 * ## The crosshair works from the keyboard
 *
 * This is the part chart libraries almost universally get wrong: hover-only
 * inspection means the values exist for mouse users and for nobody else. Here
 * the SVG is focusable, ←/→ step the crosshair, Home/End jump to the ends, and
 * the readout below is `aria-live="polite"` so each step is announced. Learned
 * in 1.2 — axe cannot press a key, so it scored the hover-only version green.
 *
 * The pointer path and the keyboard path both resolve through `nearestIndex`,
 * so the two can never disagree about which point is under the crosshair.
 *
 * ## MIN_VIEWPORT — 320
 *
 * The SVG scales to its container via `viewBox` (no fixed width), the readout
 * wraps, and `<SeriesTable>` scrolls inside its own box. Nothing forces the
 * page to scroll horizontally.
 *
 * | Rule | Concept                    | Where in this file                                       |
 * | ---- | -------------------------- | -------------------------------------------------------- |
 * | R6   | data-slot on every part    | `data-slot="time-series" / "-plot" / "-readout"`          |
 * | R7   | className merged + ...rest | `cn(...)` + `{...props}`                                  |
 * | R8   | No `isXxx`; enums          | `polarity`; annotation `kind`                             |
 * | R13  | Ecosystem first            | no charting dep — `seriesScales` + SVG is the engine      |
 * | R14  | Declares min viewport      | `data-min-viewport={String(MIN_VIEWPORT)}`                |
 * | R18  | Tailwind only              | zero inline `style`                                       |
 * | R19  | Tokens only                | `stroke-viz-*`, `fill-viz-*`, `text-muted-foreground`     |
 * | R20  | AA contrast                | axis 3.64:1 light / 3.82:1 dark; grid deliberately decorative |
 * | R23  | Loading reserves its box   | `loading` → `<Skeleton variant="chart">`, same height     |
 * | R25  | Client component           | pointer + key handlers, `useState`                        |
 * | R26  | A11y                       | `role="img"` + label + focusable + live readout + table   |
 */

import * as React from 'react';

import { cn } from '@/lib/utils';
import { Skeleton } from '@/components/ui/skeleton';
import { SeriesTable } from '@/components/ui/charts/series-table';
import {
  areaPath,
  day,
  describeSeries,
  linePath,
  nearestIndex,
  seriesScales,
  ticks,
  type Annotation,
  type AnnotationKind,
  type Point,
} from '@/components/ui/charts/scale';

export const MIN_VIEWPORT = 320 as const;

/** Internal drawing width in user units. The viewBox scales it to any container. */
const W = 900;
const PAD_LEFT = 44;
const PAD_TOP = 14;

/**
 * Annotation marks differ by SHAPE first and hue second. A photocopy, a
 * greyscale print, and a colour-blind reader all keep the distinction.
 */
const MARK: Record<AnnotationKind, { className: string; d: (x: number, y: number) => string }> = {
  publish: {
    className: 'fill-viz-annotation-publish',
    // circle, drawn as a path so all three share one element type
    d: (x, y) => `M${x - 3.5},${y}a3.5,3.5 0 1,0 7,0a3.5,3.5 0 1,0 -7,0`,
  },
  release: {
    className: 'fill-viz-annotation-release',
    d: (x, y) => `M${x},${y - 4}L${x + 4},${y}L${x},${y + 4}L${x - 4},${y}Z`, // diamond
  },
  action: {
    className: 'fill-viz-annotation-action',
    d: (x, y) => `M${x},${y - 4}L${x + 4},${y + 3.5}L${x - 4},${y + 3.5}Z`, // triangle
  },
};

export interface TimeSeriesProps extends Omit<React.ComponentProps<'figure'>, 'children'> {
  points: readonly Point[];
  annotations?: readonly Annotation[];
  /** Drawing height in user units. The rendered height follows the container width. */
  height?: number;
  /** Series name — used in the caption, the accessible label and the readout. */
  label?: string;
  /** Noun for the values, e.g. "views". */
  unit?: string;
  /** Render the data table visibly under the chart instead of `sr-only`. */
  showTable?: boolean;
  /**
   * Render a `<Skeleton variant="chart" />` placeholder.
   *
   * A chart's data is in flight on first paint essentially always, so this is
   * the state the component spends its first frames in — and the one most often
   * left as a spinner, which reserves no space and guarantees a layout shift the
   * moment the series lands.
   */
  loading?: boolean;
}

export const TimeSeries = React.forwardRef<HTMLElement, TimeSeriesProps>(function TimeSeries(
  {
    points,
    annotations = [],
    height = 220,
    label,
    unit,
    showTable = false,
    loading = false,
    className,
    ...props
  },
  ref,
) {
  const [cursor, setCursor] = React.useState<number | null>(null);
  const svgRef = React.useRef<SVGSVGElement>(null);

  const scales = React.useMemo(
    () => seriesScales(points, W - PAD_LEFT, height - PAD_TOP, PAD_TOP),
    [points, height],
  );
  // Shift the plot right of the axis labels without threading an offset through
  // every scale call.
  const px = React.useCallback((i: number) => PAD_LEFT + scales.x(i), [scales]);

  const line = linePath(scales);
  const axisTicks = React.useMemo(() => ticks(scales, 4), [scales]);
  const indexByDay = React.useMemo(
    () => new Map(scales.points.map((p, i) => [day(p.t), i])),
    [scales.points],
  );

  const last = scales.points.length - 1;

  const move = React.useCallback(
    (next: number) => setCursor(Math.max(0, Math.min(last, next))),
    [last],
  );

  const onKeyDown = (event: React.KeyboardEvent<SVGSVGElement>) => {
    const current = cursor ?? 0;
    switch (event.key) {
      case 'ArrowRight':
        move(current + 1);
        break;
      case 'ArrowLeft':
        move(current - 1);
        break;
      case 'Home':
        move(0);
        break;
      case 'End':
        move(last);
        break;
      case 'Escape':
        setCursor(null);
        return; // no preventDefault — Escape may close an enclosing overlay
      default:
        return;
    }
    // Arrow keys scroll the page by default; a focused chart owns them.
    event.preventDefault();
  };

  const onPointerMove = (event: React.PointerEvent<SVGSVGElement>) => {
    const box = svgRef.current?.getBoundingClientRect();
    if (!box || box.width === 0) return;
    const userX = ((event.clientX - box.left) / box.width) * W - PAD_LEFT;
    move(nearestIndex(scales, userX, W - PAD_LEFT));
  };

  // Loading is checked BEFORE the not-enough-data branch: data still in flight
  // is not the same claim as "this metric has no history", and telling a reader
  // the second while the first is true is simply wrong.
  //
  // Every hook above this point runs unconditionally — the guard sits after them
  // on purpose, so toggling `loading` never changes the hook order.
  if (loading) {
    return (
      <Skeleton
        variant="chart"
        data-slot="time-series"
        data-min-viewport={String(MIN_VIEWPORT)}
        className={className}
      />
    );
  }

  // Below two points there is no line to draw. Say why, rather than rendering an
  // empty box that reads as a bug — a series genuinely cannot be back-filled.
  if (!line) {
    return (
      <figure
        ref={ref}
        data-slot="time-series-empty"
        data-min-viewport={String(MIN_VIEWPORT)}
        className={cn('m-0 w-full rounded-lg border border-border p-6', className)}
        {...props}
      >
        <p className="text-sm text-muted-foreground">
          {scales.points.length === 0
            ? 'No data yet.'
            : `Only ${scales.points.length} point so far.`}{' '}
          A trend needs at least two observations, and history cannot be back-filled.
        </p>
      </figure>
    );
  }

  const active = cursor === null ? null : scales.points[cursor];

  return (
    <figure
      ref={ref}
      data-slot="time-series"
      data-min-viewport={String(MIN_VIEWPORT)}
      // `w-full` is load-bearing, not cosmetic. The plot sizes itself from the
      // container via `viewBox` + `w-full`, so a figure that collapses to
      // zero width paints NOTHING — and a bare <figure> is a flex/grid item
      // that does exactly that inside any centered parent. Caught in the
      // browser; jsdom reports every box as 0×0 and cannot see it.
      className={cn('m-0 flex w-full flex-col gap-2', className)}
      {...props}
    >
      {label && (
        <figcaption className="text-xs text-muted-foreground">
          {label}
          <span className="sr-only">, </span>
          <span aria-hidden> · </span>
          {day(scales.points[0].t)} → {day(scales.points[last].t)}
        </figcaption>
      )}

      <svg
        ref={svgRef}
        data-slot="time-series-plot"
        viewBox={`0 0 ${W} ${height}`}
        className={cn(
          'block w-full touch-pan-y rounded-md',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
        )}
        role="img"
        aria-label={`${describeSeries(points, label)} Focus this chart and use the left and right arrow keys to read individual values.`}
        tabIndex={0}
        onKeyDown={onKeyDown}
        onPointerMove={onPointerMove}
        onPointerLeave={() => setCursor(null)}
        onBlur={() => setCursor(null)}
      >
        {/* Grid + axis. Decorative weight for the lines, real contrast for the
            labels — the label is what tells you where zero is. */}
        {axisTicks.map((value) => {
          const y = scales.y(value);
          return (
            <g key={value}>
              <line
                x1={PAD_LEFT}
                y1={y}
                x2={W}
                y2={y}
                className="stroke-viz-grid"
                strokeWidth={1}
                aria-hidden
              />
              <text
                x={PAD_LEFT - 8}
                y={y}
                dominantBaseline="middle"
                textAnchor="end"
                className="fill-muted-foreground text-xs tabular-nums"
                aria-hidden
              >
                {Math.round(value).toLocaleString()}
              </text>
            </g>
          );
        })}
        <line
          x1={PAD_LEFT}
          y1={PAD_TOP}
          x2={PAD_LEFT}
          y2={height}
          className="stroke-viz-axis"
          strokeWidth={1}
          aria-hidden
        />

        {/* The series paths are built in unshifted scale space, so they live in
            one translated group. Everything outside this <g> — annotations,
            crosshair — positions with `px()`, which adds the same offset.
            Two ways to say "left edge" in one file is how coordinate bugs
            start; this is the seam between them. */}
        <g transform={`translate(${PAD_LEFT} 0)`}>
          <path d={areaPath(scales, height)} className="fill-chart-1 opacity-10" aria-hidden />
          <path
            d={line}
            fill="none"
            strokeWidth={2}
            strokeLinejoin="round"
            strokeLinecap="round"
            className="stroke-chart-1"
          />
        </g>

        {annotations.map((annotation) => {
          const index = indexByDay.get(day(annotation.t));
          if (index == null) return null;
          const kind: AnnotationKind = annotation.kind ?? 'action';
          const mark = MARK[kind];
          const x = px(index);
          return (
            <g key={`${annotation.t}-${annotation.label}`} data-annotation-kind={kind}>
              <line
                x1={x}
                y1={PAD_TOP}
                x2={x}
                y2={height}
                className="stroke-viz-axis opacity-50"
                strokeWidth={1}
                strokeDasharray="3 3"
                aria-hidden
              />
              <path d={mark.d(x, PAD_TOP)} className={mark.className}>
                {/* `<title>` is the SVG-native tooltip AND accessible name for
                    the shape — no Popover needed for a label this short. */}
                <title>{`${day(annotation.t)} — ${kind}: ${annotation.label}`}</title>
              </path>
            </g>
          );
        })}

        {cursor !== null && active && (
          <g aria-hidden>
            <line
              x1={px(cursor)}
              y1={PAD_TOP}
              x2={px(cursor)}
              y2={height}
              className="stroke-viz-crosshair opacity-50"
              strokeWidth={1}
            />
            <circle
              cx={px(cursor)}
              cy={scales.y(active.v)}
              r={4}
              className="fill-chart-1 stroke-background"
              strokeWidth={2}
            />
          </g>
        )}
      </svg>

      {/* The readout is both the tooltip and the live region. One element, so a
          keyboard user and a mouse user are never told different things. */}
      <div
        data-slot="time-series-readout"
        className="flex flex-wrap items-baseline justify-between gap-x-4 text-xs text-muted-foreground tabular-nums"
      >
        <span aria-hidden>{scales.min.toLocaleString()}</span>
        <output aria-live="polite" className="font-medium text-foreground">
          {active
            ? `${day(active.t)} · ${active.v.toLocaleString()}${unit ? ` ${unit}` : ''}`
            : ''}
        </output>
        <span aria-hidden>{scales.max.toLocaleString()}</span>
      </div>

      <SeriesTable
        series={[{ label: label ?? 'Value', points }]}
        caption={`${label ?? 'Series'} — full data${unit ? ` (${unit})` : ''}`}
        hidden={!showTable}
      />
    </figure>
  );
});

/**
 * @interlace/ui — chart scales and series math
 *
 * Every number a chart draws comes from here. Nothing in this file imports
 * React, touches the DOM, or renders anything — which is the point: it is the
 * part of a visualisation that can be *proved* correct, so it carries the
 * 100/100/100/100 coverage gate while the SVG above it is checked by stories
 * and axe.
 *
 * There is no charting dependency, and that is a decision rather than an
 * omission. A shadcn-registry item must install from a bare `npx shadcn add`
 * with every import resolvable, and d3/recharts/visx each want to own layout.
 * The named exit: if one surface ever needs >5k points with a live crosshair,
 * *that component* goes to canvas — it does not drag a library into the other
 * twenty. See VISUALIZATION_PHILOSOPHY.md.
 */

/** One observation. `v: null` is a real gap in the data, not a zero. */
export interface Point {
  /** ISO date, or any string that sorts correctly. */
  t: string;
  v: number | null;
}

/** A mark drawn ON the series — a publish, a release, a manual action. */
export interface Annotation {
  t: string;
  label: string;
  kind?: AnnotationKind;
}

export const ANNOTATION_KINDS = ['publish', 'release', 'action'] as const;
export type AnnotationKind = (typeof ANNOTATION_KINDS)[number];

/** Direction of travel. `flat` exists so callers never have to treat 0 as "up". */
export type Direction = 'up' | 'down' | 'flat';

/** A point that survived `numeric()` — `v` is narrowed to a number. */
export type NumericPoint = { t: string; v: number };

/**
 * Drop the gaps.
 *
 * A `null` is not plottable and must not become a 0 — a day we did not measure
 * is not a day the metric was zero, and averaging over it silently invents
 * data. Callers that want interpolation must ask for it explicitly.
 */
export const numeric = (points: readonly Point[]): NumericPoint[] =>
  points.filter((p): p is NumericPoint => typeof p.v === 'number' && Number.isFinite(p.v));

/** The x/y projectors plus the observed domain, for one series in one box. */
export interface Scales {
  points: NumericPoint[];
  x: (index: number) => number;
  y: (value: number) => number;
  min: number;
  max: number;
}

/**
 * Project a series into an SVG box.
 *
 * Two edge cases are handled here rather than in every component:
 *
 *  - **A single point** has no horizontal extent, so it is centred instead of
 *    being pinned to x=0 where it reads as the start of a line that never drew.
 *  - **A flat series** has a zero span. Dividing by it yields NaN, and clamping
 *    the span to 1 would pin the line to the top edge — which looks like a
 *    metric at its maximum rather than one that never moved. It is centred.
 */
export function seriesScales(
  points: readonly Point[],
  width: number,
  height: number,
  pad = 4,
): Scales {
  const pts = numeric(points);
  const values = pts.map((p) => p.v);
  const min = values.length ? Math.min(...values) : 0;
  const max = values.length ? Math.max(...values) : 0;
  const span = max - min;
  const last = pts.length - 1;

  const x = (index: number): number => (last > 0 ? (index / last) * width : width / 2);

  const y = (value: number): number =>
    span === 0 ? height / 2 : height - pad - ((value - min) / span) * (height - pad * 2);

  return { points: pts, x, y, min, max };
}

/** An SVG path `d` for the series polyline. Empty string for <2 points. */
export const linePath = (scales: Scales): string =>
  scales.points.length < 2
    ? ''
    : scales.points.map((p, i) => `${i ? 'L' : 'M'}${scales.x(i)},${scales.y(p.v)}`).join('');

/** The polyline closed down to the baseline, for an area fill. */
export const areaPath = (scales: Scales, height: number): string => {
  const line = linePath(scales);
  if (!line) return '';
  return `${line}L${scales.x(scales.points.length - 1)},${height}L${scales.x(0)},${height}Z`;
};

/** First → last change, in absolute and percentage terms. */
export interface DeltaResult {
  from: number;
  to: number;
  abs: number;
  /** `null` when the baseline is 0 — a percentage change from nothing is undefined, not infinite. */
  pct: number | null;
  direction: Direction;
}

export function delta(points: readonly Point[]): DeltaResult | null {
  const pts = numeric(points);
  if (pts.length < 2) return null;
  const from = pts[0].v;
  const to = pts[pts.length - 1].v;
  const abs = to - from;
  return {
    from,
    to,
    abs,
    pct: from === 0 ? null : (abs / Math.abs(from)) * 100,
    direction: abs > 0 ? 'up' : abs < 0 ? 'down' : 'flat',
  };
}

/** ISO timestamp → `YYYY-MM-DD`. Charts key annotations by day, not by instant. */
export const day = (t: string): string => t.slice(0, 10);

/**
 * The accessible name for a series.
 *
 * Axe cannot read an SVG, and a screen reader handed `role="img"` with no label
 * announces "image". This is the sentence that replaces the picture — every
 * chart in this package owes one, alongside its `<SeriesTable>`.
 */
export function describeSeries(points: readonly Point[], label?: string): string {
  const pts = numeric(points);
  const name = label ?? 'Series';
  if (pts.length === 0) return `${name}: no data`;
  if (pts.length === 1) return `${name}: a single value, ${pts[0].v}, on ${day(pts[0].t)}`;
  const d = delta(pts)!;
  const move =
    d.direction === 'flat'
      ? 'unchanged'
      : `${d.direction} ${Math.abs(d.abs).toLocaleString()}${
          d.pct === null ? '' : ` (${Math.abs(d.pct).toFixed(1)}%)`
        }`;
  return (
    `${name}: ${pts.length} points from ${day(pts[0].t)} to ${day(pts[pts.length - 1].t)}, ` +
    `${d.from.toLocaleString()} to ${d.to.toLocaleString()}, ${move}. ` +
    `Range ${Math.min(...pts.map((p) => p.v)).toLocaleString()} to ` +
    `${Math.max(...pts.map((p) => p.v)).toLocaleString()}.`
  );
}

/**
 * Evenly spaced axis values across the observed domain.
 *
 * Deliberately NOT "nice" rounded ticks. A metric that ran 3,412 → 3,588 gets
 * ticks inside that band; rounding out to 0–4,000 would flatten the only thing
 * the reader came for. The axis labels the data, not a textbook scale.
 */
export function ticks(scales: Scales, count = 3): number[] {
  if (count < 2 || scales.points.length === 0) return [];
  if (scales.min === scales.max) return [scales.min];
  const step = (scales.max - scales.min) / (count - 1);
  return Array.from({ length: count }, (_, i) => scales.min + step * i);
}

/**
 * Index of the point nearest an x position, in SVG user units.
 *
 * Shared by the pointer crosshair and the arrow-key crosshair so the two can
 * never disagree about which point is "here" — a keyboard user and a mouse user
 * read the same tooltip.
 */
export function nearestIndex(scales: Scales, xPosition: number, width: number): number {
  const last = scales.points.length - 1;
  if (last <= 0) return 0;
  const ratio = width === 0 ? 0 : xPosition / width;
  return Math.max(0, Math.min(last, Math.round(ratio * last)));
}

/** Compact number formatting for dense rows — 12.4k, 3.1M. */
export function compact(value: number): string {
  const abs = Math.abs(value);
  if (abs >= 1e9) return `${(value / 1e9).toFixed(1)}B`;
  if (abs >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
  if (abs >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
  return value.toLocaleString();
}
